<?php require_once __DIR__.'/includes/functions.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$action=(string)($_POST['action']??'');try{if($action==='delete'){$pdo->prepare('UPDATE cars SET is_active=0 WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Car listing archived.');go('admin.php');}if($action==='save'){$id=(int)($_POST['id']??0);$fields=['brand','name','body_type','fuel','transmission','price_min','price_max','engine','power','torque','mileage','drive_type','safety','boot_space','seating','tagline','image_url'];$vals=[];foreach($fields as $f)$vals[$f]=trim((string)($_POST[$f]??''));if($vals['brand']===''||$vals['name']===''||(int)$vals['price_min']<1)throw new RuntimeException('Brand, name and valid starting price are required.');if($id){$sets=implode(',',array_map(fn($f)=>"$f=?",array_keys($vals)));$st=$pdo->prepare("UPDATE cars SET $sets WHERE id=?");$st->execute([...array_values($vals),$id]);}else{$cols=implode(',',array_keys($vals));$marks=implode(',',array_fill(0,count($vals),'?'));$st=$pdo->prepare("INSERT INTO cars($cols) VALUES($marks)");$st->execute(array_values($vals));}flash('success','Car listing saved.');go('admin.php');}}catch(Throwable $e){$error=$e->getMessage();}}$cars=$pdo->query('SELECT id,brand,name,price_min,is_active FROM cars ORDER BY brand,name')->fetchAll();$pageTitle='Admin';require __DIR__.'/includes/header.php'; ?>
<div class="page-intro"><span class="eyebrow">CATALOGUE CONTROL</span><h1>Admin dashboard</h1><p class="muted">Manage the car catalogue displayed on AutoVerse.</p></div>
<div class="panel admin-form"><h2>Add a car listing</h2><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(token()) ?>"><input type="hidden" name="action" value="save"><div class="form-grid"><?php foreach(['brand'=>'Brand','name'=>'Model name','body_type'=>'Body type','fuel'=>'Fuel','transmission'=>'Transmission','price_min'=>'Starting price (INR)','price_max'=>'Maximum price (INR)','engine'=>'Engine / motor','power'=>'Power','torque'=>'Torque','mileage'=>'Mileage / range','drive_type'=>'Drive type','safety'=>'Safety','boot_space'=>'Boot space','seating'=>'Seats','tagline'=>'Short description','image_url'=>'Image URL'] as $k=>$label): ?><div><label><?= e($label) ?></label><input name="<?= e($k) ?>" <?= in_array($k,['brand','name','price_min'])?'required':'' ?>></div><?php endforeach; ?></div><button class="btn">Add listing</button></form></div>
<div class="panel table-wrap admin-list"><table><thead><tr><th>Brand</th><th>Model</th><th>Starting price</th><th>Action</th></tr></thead><tbody><?php foreach($cars as $c): ?><tr><td><?= e($c['brand']) ?></td><td><?= e($c['name']) ?></td><td><?= money($c['price_min']) ?></td><td><form method="post" onsubmit="return confirm('Archive this listing?')"><input type="hidden" name="csrf" value="<?= e(token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="text-button">Archive</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<?php require __DIR__.'/includes/footer.php'; ?>
